<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeRequiredVO;

trait ConsentPurposeRequiredAttributeHolder
{
    protected ConsentPurposeRequiredVO|bool|null $required = null;
    protected bool $requiredAssigned = false;

    public function getRequiredOrCurrent(ConsentPurposeRequiredVO $required): ConsentPurposeRequiredVO
    {
        if ($this->requiredAssigned) {
            \assert(null !== $this->required);
            return ConsentPurposeRequiredVO::from($this->required);
        } else {
            return $required;
        }
    }
    public function requiredTryBuildInitial(ConstraintFailList $error): ?ConsentPurposeRequiredVO
    {
        return  ConsentPurposeRequiredVO::tryFrom($this->requiredAssigned ? $this->required : null, $error);
    }
    public function required(ConsentPurposeRequiredVO|bool $required): static
    {
        $this->required = $required;
        $this->requiredAssigned = true;
        return $this;
    }
    public function isRequired(): ?bool
    {
        return $this->required instanceof ConsentPurposeRequiredVO ? $this->required->value() : $this->required;
    }
    public function isRequiredAssigned(): bool
    {
        return $this->requiredAssigned;
    }
    public function writeRequiredTo(mixed $att): void
    {
        if ($this->requiredAssigned) {
            \assert(null !== $this->required);
            $att->required($this->required);
        }
    }
    public function readRequiredFrom(mixed $att): void
    {
        if ($att->isRequiredAssigned()) {
            $required = $att->isRequired();
            \assert(null !== $required);
            $this->required($required);
        }
    }
    public function unsetRequired(): static
    {
        $this->requiredAssigned = false;
        return $this;
    }
    protected function withDefaultRequired(): void
    {
    }
    protected function withAssertedRequiredRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->requiredAssigned = $this->requiredAssigned) {
            $value->required = ConsentPurposeRequiredVO::tryFrom($this->required, $errorsList);
        }
    }
}
